import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.sc8Z_ZE3.js";const p=JSON.parse('{"title":"Contribute","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/index.md","filePath":"contribute/index.md"}'),n={name:"contribute/index.md"};function i(s,e,c,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h1><p>Octryx AI is open source under the Apache License 2.0 and built in the open from the alpha on. It is early, and help moves it fast: code, tests, documentation, and reports from real runs in your own team.</p><p>The source is at <a href="https://github.com/octryx-ai/octryx" target="_blank" rel="noreferrer">github.com/octryx-ai/octryx</a>, the benchmark cases at <a href="https://github.com/octryx-ai/octryx-bench" target="_blank" rel="noreferrer">github.com/octryx-ai/octryx-bench</a>.</p><h2 id="ways-to-help" tabindex="-1">Ways to help <a class="header-anchor" href="#ways-to-help" aria-label="Permalink to &quot;Ways to help&quot;">​</a></h2><ul><li><strong>Try it and report.</strong> Run the <a href="/docs/start/first-run">first run</a> on your machine and tell us where it broke or was unclear: see <a href="/docs/contribute/report">Report a bug or a security issue</a>. A report with the run&#39;s record is worth more than a guess.</li><li><strong>Fix a good first issue.</strong> Small, well-bounded changes with their file, test and acceptance: see <a href="/docs/contribute/good-first-issues">Good first issues</a>.</li><li><strong>Add a connection or a check.</strong> Connections and checks are the parts that grow fastest with new teams. See <a href="/docs/connections/">Connections</a>.</li><li><strong>Improve this wiki.</strong> Every page says its real status. If a page is wrong or out of date, a pull request is the fastest fix.</li></ul><h2 id="what-a-good-change-looks-like" tabindex="-1">What a good change looks like <a class="header-anchor" href="#what-a-good-change-looks-like" aria-label="Permalink to &quot;What a good change looks like&quot;">​</a></h2><p>A good change here is small, easy to verify, and leaves the architecture at least as clean as before. One correct, verified slice beats a broad rewrite.</p><ul><li><a href="/docs/contribute/dev-setup">Set up your development environment</a></li><li><a href="/docs/contribute/code-style">Code style</a></li><li><a href="/docs/contribute/pull-requests">How a pull request goes in</a></li></ul><h2 id="code-of-conduct" tabindex="-1">Code of conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to &quot;Code of conduct&quot;">​</a></h2><p>The project follows the <a href="https://www.contributor-covenant.org/version/2/1/code_of_conduct/" target="_blank" rel="noreferrer">Contributor Covenant 2.1</a>, unchanged. To reach the maintainers about a conduct issue, send a private report through <strong>Security › Report a vulnerability</strong> in the repository, or message a maintainer on GitHub; there is no e-mail address.</p><h2 id="licence" tabindex="-1">Licence <a class="header-anchor" href="#licence" aria-label="Permalink to &quot;Licence&quot;">​</a></h2><p>Octryx AI is licensed under the Apache License, Version 2.0: the platform, the launcher, the VS Code extension and the plugins. Contributions are accepted under the same licence (inbound = outbound, section 5 of the licence); there is no contributor licence agreement.</p><p>Third-party components keep their own licences, as declared in their package metadata. The repository&#39;s <code>NOTICE</code> file names the ones that need it:</p><ul><li>code-review-graph, under MIT;</li><li>the Kyutai speech model weights, under CC-BY-4.0, downloaded at runtime and not shipped;</li><li>a trademark note for the icons from Simple Icons and Iconify and for the Loki logo.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://octryx.ai/roadmap" target="_blank" rel="noreferrer">Roadmap on octryx.ai</a></li><li><a href="/docs/start/status">Status and results</a></li></ul>',16)])])}const f=t(n,[["render",i]]);export{p as __pageData,f as default};
